public static final String MODID = "create_mechanical_spawner";
public static final String DISPLAY_NAME = "Create Mechanical Spawner";
public static final CreateRegistrate REGISTRATE = CreateRegistrate.create((String)"create_mechanical_spawner");
public static final Logger LOGGER;

public CreateMechanicalSpawner() {
    IEventBus modEventBus = FMLJavaModLoadingContext.get().getModEventBus();
    REGISTRATE.registerEventListeners(modEventBus);
    MinecraftForge.EVENT_BUS.register((Object)this);
    ModConfigs.register();
    ModBlocks.register();
    ModBlockEntities.register();
    ModRecipeTypes.register(modEventBus);
    ModFluids.register();
    ModCreativeTabs.register(modEventBus);
    modEventBus.addListener(this::doClientStuff);
    modEventBus.addListener(ModDataGen::gatherData);
    this.generateLangEntries();
}

private void generateLangEntries() {
    CreateMechanicalSpawner.registrate().addRawLang("itemGroup.create_mechanical_spawner:main", DISPLAY_NAME);
    CreateMechanicalSpawner.registrate().addRawLang("config.jade.plugin_create_mechanical_spawner.spawner_data", "Mechanical spawner data");
    CreateMechanicalSpawner.registrate().addRawLang("create_mechanical_spawner.recipe.spawner", "Spawner recipe");
    CreateMechanicalSpawner.registrate().addRawLang("create_mechanical_spawner.generic.biome_dependant", "Biome dependant");
    CreateMechanicalSpawner.registrate().addRawLang("create_mechanical_spawner.generic.with_custom_loot", "Custom loot with loot collector");
    CreateMechanicalSpawner.registrate().addRawLang("create_mechanical_spawner.spawner.tooltip.with_loot_collector", "Loot collector found!");
    CreateMechanicalSpawner.registrate().addRawLang("create_mechanical_spawner.spawner.tooltip.progress", "Progress: %d%%");
    CreateMechanicalSpawner.registrate().addRawLang("create_mechanical_spawner.spawner.scrollValue.label", "Spawn at height (in blocks)");
    CreateMechanicalSpawner.registrate().addRawLang("block.create_mechanical_spawner.mechanical_spawner.tooltip", "MECHANICAL SPAWNER");
    CreateMechanicalSpawner.registrate().addRawLang("block.create_mechanical_spawner.mechanical_spawner.tooltip.summary", "Spawns _Mobs_ with spawn liquid.");
    CreateMechanicalSpawner.registrate().addRawLang("create_mechanical_spawner.ponder.spawner.header", "Spawning living entities");
    CreateMechanicalSpawner.registrate().addRawLang("create_mechanical_spawner.ponder.spawner.text_1", "The Spawner uses rotational force and special fluids to spawn entities");
    CreateMechanicalSpawner.registrate().addRawLang("create_mechanical_spawner.ponder.spawner.text_2", "Its powered from the bottom");
    CreateMechanicalSpawner.registrate().addRawLang("create_mechanical_spawner.ponder.spawner.text_3", "Fluid input can go in from any horizontal side");
    CreateMechanicalSpawner.registrate().addRawLang("create_mechanical_spawner.ponder.spawner.text_4", "Spawn point can be configured");
    CreateMechanicalSpawner.registrate().addRawLang("create_mechanical_spawner.ponder.spawner.text_5", "A loot collector can be placed in the spawn point to automatically collect loot without spawning the entity");
