import net.minecraftforge.fluids.ForgeFlowingFluid;

public class SpawnerPonderScenes {
    public static void spawner(SceneBuilder builder, SceneBuildingUtil util) {
        CreateSceneBuilder scene = new CreateSceneBuilder(builder);
        scene.title("spawner", "Spawning living entities");
        scene.configureBasePlate(0, 2, 6);
        scene.showBasePlate();
        BlockPos spawnerPos = util.grid().at(2, 3, 2);
        Selection spawnerSelection = util.select().position(2, 3, 2);
        Selection spawnerShaftSelection = util.select().position(2, 1, 2).add(util.select().position(2, 2, 2));
        Selection mixerPlateShaftSelection = util.select().position(1, 1, 5);
        scene.world().showSection(util.select().layer(1).substract(spawnerShaftSelection).substract(mixerPlateShaftSelection), Direction.DOWN);
        scene.world().showSection(spawnerSelection, Direction.UP);
        Selection allElements = util.select().everywhere();
        Selection mixerSelection = util.select().fromTo(0, 2, 3, 3, 5, 5).add(mixerPlateShaftSelection);
        scene.addKeyframe();
        scene.idle(10);
        scene.overlay().showOutlineWithText(spawnerSelection, 50).text("The Spawner uses rotational force and special fluids to spawn entities").pointAt(util.vector().blockSurface(spawnerPos, Direction.WEST).m_82520_(-0.5, 0.4, 0.0)).placeNearTarget();
        scene.idle(60);
        scene.addKeyframe();
        scene.idle(35);
        scene.idle(5);
        scene.world().showSection(spawnerShaftSelection, Direction.DOWN);
        scene.overlay().showText(50).text("Its powered from the bottom").pointAt(util.vector().blockSurface(spawnerPos, Direction.DOWN).m_82520_(-0.5, 0.4, 0.0)).placeNearTarget();
        scene.world().setKineticSpeed(allElements, -64.0f);
        scene.idle(60);
        scene.addKeyframe();
        scene.world().showSection(mixerSelection, Direction.EAST);
        scene.idle(35);
        scene.overlay().showText(50).text("Fluid input cab go in fro any horizontal side").pointAt(util.vector().blockSurface(spawnerPos, Direction.NORTH).m_82520_(-0.5, 0.4, 0.0)).placeNearTarget();
        FluidStack spawnFluid = new FluidStack(((ForgeFlowingFluid.Flowing)ModFluids.ENDERMAN.get()).m_5613_(), 1000);
        scene.world().modifyBlockEntity(spawnerPos, SpawnerBlockEntity.class, ms -> ms.getFluidTank().setFluid(spawnFluid));
        scene.idle(60);
        scene.addKeyframe();
        scene.overlay().showText(50).text("Spawn point can be configured").pointAt(util.vector().blockSurface(spawnerPos, Direction.WEST).m_82520_(-0.5, 0.4, 0.0)).placeNearTarget();
        scene.overlay().showCenteredScrollInput(spawnerPos, Direction.NORTH, 60);
        scene.idle(10);
        scene.overlay().showOutline(PonderPalette.WHITE, new Object(), util.select().position(spawnerPos.m_121945_(Direction.UP)), 5);

