import net.minecraft.data.PackOutput;
import net.minecraftforge.data.event.GatherDataEvent;

public class ModDataGen {
    public static void gatherData(GatherDataEvent event) {
        DataGenerator generator = event.getGenerator();
        PackOutput output = generator.getPackOutput();
        if (event.includeServer()) {
            generator.addProvider(true, (DataProvider)new SpawnerRecipeGen(output));
            generator.addProvider(true, (DataProvider)new CraftingRecipeGen(output));
            generator.addProvider(true, (DataProvider)new CreateMixingRecipeGen(output));
            generator.addProvider(true, (DataProvider)new CompatRecipeGen(output));
        }
    }
}

