package com.hlysine.create_power_loader.ponder;

import com.simibubi.create.foundation.ponder.CreateSceneBuilder;
import net.createmod.ponder.api.PonderPalette;
import net.createmod.ponder.api.scene.SceneBuilder;
import net.createmod.ponder.api.scene.SceneBuildingUtil;
import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;

public class AndesiteChunkLoaderScenes {
    public static void basicUsage(SceneBuilder builder, SceneBuildingUtil util) {
        CreateSceneBuilder scene = new CreateSceneBuilder(builder);
        scene.title("andesite_chunk_loader_basic", "Basic Usage of the Andesite Chunk Loader");
        scene.configureBasePlate(0, 0, 5);
        scene.world().showSection(util.select().layer(0), Direction.UP);
        scene.idle(5);
        scene.world().showSection(util.select().layers(1, 2), Direction.DOWN);
        scene.idle(10);
        BlockPos loaderPos = new BlockPos(2, 2, 2);
        scene.effects().rotationSpeedIndicator(loaderPos);
        scene.effects().indicateSuccess(loaderPos);
        scene.idle(10);
        scene.overlay().showText(60).colored(PonderPalette.GREEN).text("The chunk loader keeps the current chunk loaded when given rotational power").placeNearTarget().attachKeyFrame().pointAt(util.vector().topOf(loaderPos));
        scene.idle(80);
        scene.world().modifyKineticSpeed(util.select().everywhere(), f -> Float.valueOf(f.floatValue() / 4.0f));
        scene.effects().rotationSpeedIndicator(loaderPos);
        scene.idle(30);
        scene.overlay().showText(50).colored(PonderPalette.RED).placeNearTarget().text("It does not work when the rotation speed is too slow").attachKeyFrame().pointAt(util.vector().topOf(loaderPos));
        scene.idle(60);
    }

    public static void redstone(SceneBuilder builder, SceneBuildingUtil util) {
        CreateSceneBuilder scene = new CreateSceneBuilder(builder);
        scene.title("andesite_chunk_loader_redstone", "Redstone and the Andesite Chunk Loader");
        scene.configureBasePlate(0, 0, 5);
        scene.world().showSection(util.select().layer(0), Direction.UP);
        scene.idle(5);
        scene.world().showSection(util.select().layers(1, 2), Direction.DOWN);
        scene.idle(20);
        BlockPos loaderPos = new BlockPos(1, 1, 3);
        scene.world().toggleRedstonePower(util.select().fromTo(3, 1, 1, 1, 1, 3));
        scene.effects().indicateRedstone(new BlockPos(3, 1, 1));
        scene.world().setKineticSpeed(util.select().fromTo(3, 1, 3, 1, 1, 3), 128.0f);
        scene.overlay().showText(60).attachKeyFrame().text("The chunk loader gives comparator output when it is active").pointAt(util.vector().blockSurface(new BlockPos(1, 1, 2), Direction.DOWN)).placeNearTarget();
        scene.idle(90);
        scene.world().toggleRedstonePower(util.select().fromTo(3, 1, 1, 1, 1, 3));
        scene.effects().indicateRedstone(new BlockPos(3, 1, 1));
        scene.world().setKineticSpeed(util.select().fromTo(3, 1, 3, 1, 1, 3), 0.0f);

