        scene.idle(10);
        BlockPos loaderPos = new BlockPos(2, 2, 2);
        scene.effects().rotationSpeedIndicator(loaderPos);
        scene.effects().indicateSuccess(loaderPos);
        scene.idle(10);
        scene.overlay().showText(80).text("The chunk loader keeps the current chunk loaded when given rotational power").placeNearTarget().attachKeyFrame().pointAt(util.vector().topOf(loaderPos));
