        scene.effects().rotationSpeedIndicator(loaderPos);
        scene.idle(20);
        Vec3 scrollSlot = util.vector().of(2.5, 2.25, 2.0);
        scene.overlay().showFilterSlotInput(scrollSlot, Direction.NORTH, 170);
        scene.overlay().showText(60).text("You can configure the loaded range through the value panel...").pointAt(scrollSlot).attachKeyFrame().placeNearTarget();
        scene.idle(70);
        scene.overlay().showControls(scrollSlot, Pointing.RIGHT, 20).rightClick();
        scene.idle(5);
        scene.world().modifyBlockEntity(loaderPos, BrassChunkLoaderBlockEntity.class, be -> be.setLoadingRange(2));
        scene.idle(15);
        scene.overlay().showText(60).colored(PonderPalette.RED).text("...but a longer range requires a higher rotation speed").pointAt(scrollSlot).placeNearTarget();
        scene.idle(80);
        scene.world().modifyKineticSpeed(util.select().everywhere(), f -> Float.valueOf(f.floatValue() * 2.0f));
        scene.effects().rotationSpeedIndicator(loaderPos);
        scene.idle(40);
    }

